INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63264202', 63264202, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individual Perumusan Rekomendasi Kebijakan Pembangunan Perkotaan Non-Wilayah Metropolitan 2 Kegiatan Koordinasi Strategis Pembangunan Perkotaan Nasional Direktorat Tata Ruang, Perkotaan, Pertanahan, Dan Penanggulangan Bencana', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 144000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Memberikan dukungan kehlian dalam pengawalan pelaksanaan pembangunan perkotaan non-wilayah metropolitan termasuk proyek prioritas di dalamnya selama periode RPJMN 2025-2029 secara umum dan RKP tahun 2026 secara khusus dengan fokus lokasi untuk untuk 1 Calon Wilayah Metropolitan (Surakarta) dan 10 Wilayah non-metropolitan (Weda, Banda Neira, Anggi, Bukittingi, Belitung, Surakarta, Toba, Morotai, Cilegon, Salatiga); 2. Membantu menyusun isu strategis untuk perkotaan non-wilayah metropolitan, baik untuk 1 Calon Wilayah Metropolitan (Surakarta) dan 10 Wilayah non-metropolitan (Weda, Banda Neira, Anggi, Bukittingi, Belitung, Surakarta, Toba, Morotai, Cilegon, Salatiga), termasuk merumuskan arah kebijakan pengembangannya untuk tahun perencanaan berikutnya dari hasil koordinasi dengan berbagai pemangku kepentingan untuk mendorong pengembangan perkotaan, rekomendasi dalam lingkup pengembangan infrastruktur, sosial, ekonomi, lingkungan serta kelembagaan dan tata kelola; 3. Membantu mengawal pembahasan regulasi dan kebijakan perkotaan non-wilayah metropolitan yang diselenggarakan K/L maupun pihak lainnya, termasuk di dalamnya pembahasan dalam dokumen kebijakan RPJPN dan RPJMN; 4. Membantu menyusun dashboard kegiatan/proyek prioritas dan database pemantauan wilayah metropolitan yang diperbarui secara berkala khususnya untuk 1 Calon Wilayah Metropolitan (Surakarta) dan 10 Wilayah non-metropolitan (Weda, Banda Neira, Anggi, Bukittingi, Belitung, Surakarta, Toba, Morotai, Cilegon, Salatiga); 5. Membantu penyiapan bahan untuk setiap rapat koordinasi/FGD/diskusi/seminar/workshop/pelatihan lintas sektor dan lintas pelaku yang dilaksanakan maupun kunjungan lapangan; 6. Bertanggungjawab atas selesainya pekerjaan hingga dihasilkan laporan yang dapat diterima oleh pihak pemberi tugas dengan hasil yang memuaskan;', '1. Merupakan Jasa Konsultan Individual dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 2. Memiliki NPWP dan memiliki status valid Konfirmasi Status Wajib Pajak (KSWP); 3. Memiliki Pendidikan minimal S2 Perencanaan Wilayah dan Kota (dibuktikan dengan ijazah); 4. Memiliki pengalaman kerja minimal 5 (lima) tahun di bidang perencanaan pembangunan perkotaan termasuk bidang monitoring dan evaluasi proyek (dibuktikan dengan surat referensi/kontrak); 5. Memiliki pengalaman pekerjaan dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 3 (tiga) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 6. Memiliki pengalaman dalam analisis data, baik secara kualitatif maupun kuantitatif, dengan menggunakan program pengolah data (dibuktikan dengan hasil tulisan dan/atau laporan formal);', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 827135);
